from collections import deque

def bfs(grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    obstacles = set()

    # Identify obstacles
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'X':
                obstacles.add((i, j))

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and (x, y) not in obstacles

    def bfs_from_start(start):
        queue = deque([(start, [start])])
        while queue:
            (x, y), path = queue.popleft()
            if (x, y) == (rows-1, cols-1):  # goal
                return path
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in [p for p, _ in queue]:
                    queue.append(((nx, ny), path + [(nx, ny)]))
        return None

    # Grouping states by distance from the goal
    distances = [[float('inf')] * cols for _ in range(rows)]
    distances[-1][-1] = 0  # goal
    queue = deque([(rows-1, cols-1)])

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and distances[nx][ny] > 1 + distances[x][y]:
                distances[nx][ny] = 1 + distances[x][y]
                queue.append((nx, ny))

    grouping = {}
    for i in range(rows):
        for j in range(cols):
            distance = distances[i][j]
            if distance not in grouping:
                grouping[distance] = []
            grouping[distance].append(grid[i][j])

    return [grouping[d] for d in sorted(grouping)]

